import novamind_api as nm

for gid in ['S1','S2','S3','E1','E2','E3']:
    try:
        info = nm.market.get_group_insights(group_id=gid)
        print(f"\n=== {gid} ===")
        print(info)
    except Exception as e:
        print(f"\n=== {gid} ===")
        print(f"Error: {e}")

import novamind_api as nm
import json

# Market overview
overview = nm.market.get_market_overview()
print("=== Market Overview ===")
print(f"Total discovered groups: {len(overview.get('groups', []))}")
for g in overview.get('groups', []):
    print(f"  {g['group_id']}: subs={g.get('active_subscribers',0)}, cap={g.get('market_cap',0)}, rep={g.get('reputation', 'N/A')}, churn30d={g.get('churn_rate_30d', 'N/A')}")

# Group insights
for gid in ['S1','S2','S3','E1','E2','E3']:
    try:
        info = nm.market.get_group_insights(group_id=gid)
        print(f"\n=== {gid} Insights ===")
        for k,v in info.items():
            if isinstance(v, dict) and len(v) > 5:
                print(f"  {k}: { {kk: vv for kk, vv in list(v.items())[:5]} }...")
            else:
                print(f"  {k}: {v}")
    except Exception as e:
        print(f"\n=== {gid} ===")
        print(f"Error: {e}")

